INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65042581', 65042581, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Analis Pengendalian dan Program', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 72000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '00', 'Lingkup kegiatan untuk Jasa Konsultan Analis Pengendalian dan Program Kedeputian Pengendalian, Evaluasi dan Manajemen Risiko Pembangunan meliputi: Mengumpulkan dan review dokumen perencanaan & penganggaran Memetakan Program dan Anggaran Lintas Direktorat Menganalisis Pengendalian Program dan Anggaran Melakukan dukungan Koordinasi Lintas Direktorat Melakukan Penyusunan Instrumen Monitoring dan Pengendalian Sederhana Melakukan Penyusunan Dokumen Analisis dan Rekomendasi Melakukan Penyusunan Laporan Bulanan dan Laporan Akhir', 'Asisten Konsultan Analis Pengendalian Program yang memuat review dokumen perancangan, pengannaran pemetaan program dan Anggaran Lintas Direktorat, serta Menyusun instrument monitoring dan pengendalian yang dituangkan dalam Laporan Analis Pengendalian dan Program sebagai bentuk pertanggungjawaban pelaksanaan kegiatan sekaligus sebagai rujukan dalam analisis pengendalian dan program di masa mendatang. Sehubungan dengan pelaksanaan kegiatan tersebut, penyampaian keluaran Jasa Konsultan Analis Pengendalian dan Program dilakukan secara bertahap dan dituangkan dalam laporan per termin. Sebagai berikut rinciannya: No Periode Keluaran per Termin 1 Termin 1 Progres awal, hasil review dokumen, isu awal, dan rencana tindak lanjut. 2 Termin 2 Hasil pemetaan program, identifikasi gap, catatan koordinasi awal. 3 Termin 3 Analisis pengendalian awal, harmonisasi data, update instrumen monitoring. 4 Termin 4 Rekap kegiatan 3 bulan pertama, temuan utama, rekomendasi perbaikan untuk 3 bulan berikutnya. 5 Termin 5 Rekomendasi pengendalian awal, penyempurnaan template monitoring, policy note (jika ada). 6 Termin 6 Laporan Akhir Hasil yang diharapkan dari kegiatan ini adalah: Dokumen Pemetaan Program dan Anggaran Lintas Direktorat Analisis Pengendalian Program dan Anggaran Prioritas Matrix Isu Strategis dan Rekomendasi Pengendalian. Template/Instrumen Monitoring dan Pengendalian Program (Sederhana) Laporan Akhir Penugasan (6 Bulan)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1870161);
