INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65043803', 65043803, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Kajian Strategi Penyelenggaraan Pelatihan, Penguatan, dan Sertifikasi Entitas Pelaksana Manajemen Risiko Pembangunan Nasional  (MRPN)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 97944000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '00', 'Lingkup kegiatan yang akan dilakukan oleh Jasa Konsultan Junior Penyusunan Kajian Strategi Penyelenggaraan Pelatihan, Penguatan, dan Sertifikasi Entitas Pelaksana Manajemen Risiko Pembangunan Nasional (MRPN) adalah sebagai berikut: Melakukan asistensi Kegiatan Prioritas Utama menjadi Objek MRPN LS bersama tenaga ahli lainnya; Melakukan asistensi penyelenggaraan Pelatihan, Penguatan serta Sertifikasi kepada seluruh entitas pelaksana MRPN, yaitu: Mengidentifikasi kebutuhan pelatihan/sertifikasi berdasarkan data, wawancara teknis. Membuat usulan konsep kurikulum, modul teknis, dan konsep rencana kegiatan. Memberikan dukungan teknis dalam melakukan pemetaan penyedia pelatihan/sertifikasi dan long list/ short list opsi. Memastikan kesiapan substansi pelatihan dengan lembaga penyelenggara. Melakukan analisis kebutuhan lanjutan terkait pelaksanaan pelatihan dan sertifikasi (berbasis data dan evaluasi teknis). Melakukan evaluasi teknis terhadap pelaksanaan pelatihan/sertifikasi berdasarkan hasil observasi. Membuat draft bahan rapat, materi diskusi, dan ringkasan teknis terkait kegiatan Risk Champions. Membuat Laporan Penguatan SDM MRPN.', 'Jasa Konsultan Junior Penyusunan Kajian Strategi Penyelenggaraan Pelatihan, Penguatan, dan Sertifikasi Entitas Pelaksana Manajemen Risiko Pembangunan Nasional (MRPN) dalam mendukung Pekerjaan Direktorat Sistem dan Manajemen Risiko berkaitan dengan Penguatan SDM MRPN yang memiliki keluaran setiap terminnya sebagai berikut: No Periode Keluaran per Termin 1 Termin 1 Laporan Rancangan Strategi Penyelenggaraan Pelatihan, Penguatan serta Sertifikasi kepada seluruh entitas pelaksana MRPN. 2 Termin 2 Laporan Penyelenggaraan Asistensi Kelembagaan MRPN pada Kementerian/Lembaga dan UPR LS 3 Termin 3 Laporan penyelenggaraan asistensi pelaksanaan kegiatan penguatan kelembagaan MRPN melalui petunjuk pelaksanaan terkait penguatan kelembagaan. 4 Termin 4 Laporan Evaluasi dan Rekomendasi Pelaksanaan Penyelenggaraan Pelatihan, Penguatan serta Sertifikasi kepada seluruh Entitas Pelaksana MRPN 5 Termin 5 Laporan asistensi bimbingan teknis penyelenggaraan MRPN terkait penguatan kapasitas kelembagaan pada Kementerian/Lembaga dan pemerintah daerah. 6 Termin 6 Laporan Penyusunan Kajian Strategi Penyelenggaraan Pelatihan, Penguatan, dan Sertifikasi Entitas Pelaksana Manajemen Risiko Pembangunan Nasional (MRPN)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1871880);
