INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65022794', 65022794, 'analyze_legacy', 'Kab. Manggarai Timur', 'kabkota', 'DINAS PETERNAKAN', 'Belanja Barang untuk Dijual/Diserahkan kepada Pihak Ketiga/Pihak Lain', 'Barang', 'Pengadaan Langsung', 'Nusa Tenggara Timur, Manggarai Timur (Kab.)', 15000000, 'February 2026', 'APBD', 1, 1, '1 Paket', 'Ayam Ras Broiler (DOC);', '-; Adapun Spesifikasi teknis Ayam Ras Broiler yang dimaksud dalam pengadaan ini adalah sebagai berikut: 1. Jenis Barang Jenis barang pengadaan adalah Ayam Ras Broiler umur 1 (satu) hari (Day Old Chick/DOC) 2. Persyaratan Teknis A. Persyaratan umum a. Berasal dari pembibit ayam bibit induk (parent stock) yang bebas Salmonella pullorum yang dinyatakan dengan surat keterangan dari dinas yang membidangi fungsi peternakan dan kesehatan hewan setempat. b. Pelaksanaan pengendalian penyakit hewan menular strategis di pembibitan, di bawah tanggung jawab dokter hewan perusahaan. c. Keterangan tentang asal ayam bibit niaga (final stock) tipe pedaging, dinyatakan dengan surat keterangan dari perusahaan pembibitan ayam bibit induk (parent stock). d. Surat Keterangan Kesehatan Hewan (SKKH) dari dokter hewan berwenang. e. Berasal dari ayam bibit induk (parent stock) tipe pedaging yang berumur 24 minggu - 68 minggu dengan bobot telur tetas minimum 53 g. f. Perusahaan menginformasikan potensi performa bibit niaga tipe pedaging (bobot badan, konsumsi dan konversi pakan) berdasarkan umur per minggu kepada konsumen secara tertulis dalam bahasa Indonesia. g. Jaminan tingkat kematian kuri sampai di konsumen 2% B. Persyaratan khusus - Persyaratan kualitatif Kondisi fisik sehat : a. tampak segar dan aktif serta tidak ada kelainan bentuk, b. paruh normal, c. kedua mata terbuka, d. kondisi bulu kering dan mengembang, e. perut tidak kembung, f Ciri spesifik: Warna bulu, kaki dan paruh seragam sesuai dengan warna spesifikasi bibit niaga (final stock). - Persyaratan kuantitatif Bobot kuri di penetasan per ekor minimum 35 g. . pusar tertutup dan kering, g. dubur kering, h. kaki normal dan dapat berdiri tegak, i. tidak dehidrasi (kaki tidak kering).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1871977);
