INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65001092', 65001092, 'analyze_legacy', 'Provinsi Sumatera Utara', 'provinsi', 'Dinas Pendidikan', 'Pembangunan 2 (Dua) Ruang Kelas Baru (RKB) SMKN Seni Budaya', 'Pekerjaan Konstruksi', 'Tender', 'Sumatera Utara, Simalungun (Kab.)', 677970000, 'February 2026', 'APBD', 1, 1, '1 Paket', 'Pembangunan 2 (Dua) Ruang Kelas Baru (RKB) SMKN Seni Budaya', 'Ruang lingkup pekerjaan Konstruksi utama terdiri dari: 1. Melakukan pemeriksaan dan penilaian dokumen untuk pelaksanaan konstruksi fisik, baik dari segi kelengkapan maupun segi kebenarannya. 2. Menyusun program kerja yang meliputi jadwal waktu pelaksanaan, jadwal pengadaan bahan, jadwal penggunaan tenaga kerja, dan jadwal penggunaan peralatan berat. 3. Melaksanakan persiapan di lapangan sesuai dengan pedoman pelaksanaan. 4. Menyusun gambar pelaksanaan (shop drawing) untuk pekerjaan-pekerjaan yang memerlukannya. 5. Melaksanakan pekerjaan konstruksi fisik di lapangan sesuai dengan dokumen pelaksanaan. 6. Melaksanakan pelaporan pelaksanaan konstruksi fisik, melalui rapat-rapat lapangan, laporan harian, laporan mingguan, laporan bulanan, laporan kemajuan pekerjaan, laporan persoalan yang timbul atau dihadapi, dan surat-menyurat. 7. Membuat gambar yang sesuai dengan pelaksanaan di lapangan (as built drawing) yang selesai sebelum serah terima pertama, setelah disetujui oleh penyedia jasa konsultansi pengawasan konstruksi dan diketahui oleh penyedia jasa konsultansi perencanaan konstruksi. 8. Melaksanakan perbaikan kerusakan-kerusakan yang terjadi di masa pemeliharaan konstruksi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1872271);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65040702', 65040702, 'analyze_legacy', 'Provinsi Sumatera Utara', 'provinsi', 'Dinas Pendidikan', 'Jasa Konsultansi Pengawasan Rehabilitasi Ruang Kelas SMAN 1 Sei Kepayang', 'Jasa Konsultansi', 'Seleksi', 'Sumatera Utara, Asahan (Kab.)', 30000000, 'February 2026', 'APBD', 1, 1, '1 Paket', 'Jasa Konsultansi Pengawasan Rehabilitasi Ruang Kelas SMAN 1 Sei Kepayang', 'macam pekerjaan yang dilaksanakan oleh Konsultan Pengawas adalah: (1) Penyedia jasa pengawasan konstruksi mulai bertugas sejak ditetapkan berdasarkan SPMK sampai dengan paling lambat 2 (dua) minggu setelah serah terima akhir pekerjaan oleh penyedia jasa pelaksanaan konstruksi yaitu: a. memeriksa dan mempelajari dokumen untuk pelaksanaan konstruksi yang akan dijadikan dasar dalam pengawasan pekerjaan di lapangan. b. mengawasi pemakaian bahan, peralatan dan metode pelaksanaan, serta mengawasi ketepatan waktu, dan biaya pekerjaan konstruksi. c. mengawasi pelaksanaan konstruksi dari segi kualitas, kuantitas, dan laju pencapaian volume atau realisasi fisik. d. mengumpulkan data dan informasi di lapangan untuk memecahkan persoalan yang terjadi selama pelaksanaan konstruksi. e. menyelenggarakan rapat-rapat lapangan secara berkala, membuat laporan mingguan dan bulanan pekerjaan pengawasan, dengan masukan hasil rapat-rapat lapangan, laporan harian, mingguan dan bulanan pekerjaan konstruksi yang dibuat oleh penyedia jasa pelaksanaan konstruksi. f. meneliti gambar-gambar untuk pelaksanaan (shop drawing) yang diajukan oleh penyedia jasa pelaksanaan konstruksi. g. meneliti gambar-gambar yang sesuai dengan pelaksanaan di lapangan (As Built Drawing) sebelum serah terima pertama. h. menyusun daftar cacat atau kerusakan sebelum serah terima pertama, mengawasi perbaikannya pada masa pemeliharaan, dan menyusun laporan akhir pekerjaan pengawasan. i. menyusun berita acara persetujuan kemajuan pekerjaan, berita acara pemeliharaan pekerjaan, dan serah terima pertama dan akhir pelaksanaan konstruksi sebagai kelengkapan untuk pembayaran angsuran pekerjaan konstruksi. j. bersama-sama penyedia jasa perencanaan konstruksi menyusun petunjuk pemeliharaan dan penggunaan bangunan gedung. k. membantu pengelola kegiatan dalam menyusun Dokumen Pendaftaran. l. melakukan pemeriksaan dan menyatakan kelaikan fungsi bangunan gedung terbangun sesuai dengan IMB. m. membantu pengelola kegiatan dalam penyiapan kelengkapan dokumen Sertifikat Laik Fungsi (SLF) dari Pemerintah Kabupaten atau Kota setempat. (2) Penyedia jasa pengawasan konstruksi dalam melaksanakan tugasnya bertanggung jawab secara kontraktual kepada Pejabat Penandatangan Kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1872272);
