INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65020794', 65020794, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'PENGADAAN JASA KONSULTAN JUNIOR PENYUSUNAN DOKUMEN ANALISIS CAPAIAN PERUMAHAN DAN KAWASAN PERMUKIMAN PADA PEMANTAUAN DAN EVALUASI LINGKUP PERUMAHAN DAN PERMUKIMAN', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 100000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', '1. Melaksanakan koordinasi teknis terkait penyusunan dokumen strategis sektor perumahan dan kawasan permukiman, termasuk RKP, Renstra, Renja KL, dan RKA-KL. 2. Melakukan telaah dan analisis capaian pembangunan perumahan dan kawasan permukiman untuk mengidentifikasi perkembangan, isu, dan kebutuhan tindak lanjut. 3. Memfasilitasi dan mendampingi mitra kerja K/L serta pemerintah daerah dalam proses penyusunan program dan kegiatan sektor perumahan dan kawasan permukiman. .', '1. Pendidikan minimal S1 dari jurusan teknik sipil, perencanaan wilayah kota, dan sejenisnya. 2. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta (dibuktikan dengan kontrak); 3. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi atau karakteristik lainnya yang bisa menggambarkan kesamaan); 4. Memiliki pengalaman kerja dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai total HPS/Pagu Anggaran; 5. Memiliki kemampuan dalam menyusun laporan maupun dokumen secara sistematis (dibuktikan dengan dokumen); 6. Memiliki pengalaman dalam berkoordinasi dengan Kementerian/Lembaga dan Pemerintah Daerah (dibuktikan dengan referensi).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1872805);
