INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65043556', 65043556, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Penyusunan Kajian Kepatuhan dan Risiko Strategis Baru dan Tidak Terantisipasi Manajemen Risiko Pembangunan Nasional (MRPN)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99600000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '00', 'Lingkup kegiatan yang akan dilakukan oleh Jasa Konsultan Penyusunan Kajian Kepatuhan dan Risiko Strategis Baru dan Tidak Terantisipasi Manajemen Risiko Pembangunan Nasional (MRPN) ini meliputi: Mendukung diskusi dan sinkronisasi penyusunan serta finalisasi regulasi integrasi MRPN dalam pengendalian, evaluasi, dan pelaporan kinerja instansi pemerintah. Menyusun dan finalisasi konsep integrasi MRPN ke dalam Sistem e-Monev, termasuk harmonisasi data dan alur pemantauan risiko. Membuat dan menyempurnakan konsep laporan Sinergi Implementasi Kebijakan MRPN lintas sektor dan organisasi. Memberikan asistensi penyusunan Indikasi Profil Risiko dan Profil Risiko untuk Objek MRPN LS baru serta pembaruan profil risiko eksisting. Mendukung pelaksanaan pemantauan berkala Objek MRPN LS dan membuat laporan hasil pemantauan, termasuk tindak lanjut hasil pengawasan dan kepatuhan. Memberikan asistensi pelaksanaan perlakuan risiko serta melakukan reviu awal hasil perlakuan risiko untuk Objek MRPN LS. Mendukung penyusunan, pembahasan, dan finalisasi Laporan Penyelenggaraan dan Laporan Konsolidasi Objek MRPN LS pada UPR LS. Mendukung sinkronisasi dan penyusunan konsep integrasi MRPN dalam Laporan Kinerja Instansi Pemerintah. Membuat konsep integrasi MRPN dalam Laporan Kinerja Instansi Pemerintah', 'Dalam rangka mendukung pelaksanaan tugas Direktorat Sistem dan Manajemen Risiko, Jasa Konsultan Penyusunan Kajian Kepatuhan dan Risiko Strategis Baru dan Tidak Terantisipasi Manajemen Risiko Pembangunan Nasional (MRPN) memiliki keluaran berupa Laporan Penyusunan Kajian Kepatuhan dan Risiko Strategis Baru dan Tidak Terantisipasi Manajemen Risiko Pembangunan Nasional (MRPN) sebagai keluaran utama kegiatan. Laporan akhir tersebut disusun berdasarkan hasil pelaksanaan kegiatan secara berkesinambungan yang didukung oleh laporan tiap termin yang diterbitkan dengan rincian sebagai berikut: No Periode Keluaran per Termin 1 Termin 1 Laporan Perencanaan Kepatuhan dan Risiko Strategis Baru dan Tidak Terantisipasi MRPN 2 Termin 2 Laporan Integrasi Kepatuhan dan Risiko Strategis Baru dan Tidak Terantisipasi MRPN dalam Pengendalian dan Pelaporan 3 Termin 3 Laporan Draft Awal Tindak Lanjut Kepatuhan dan Penanganan Risiko Strategis Baru dan Tidak Terantisipasi MRPN 4 Termin 4 Laporan Tindak Lanjut Kepatuhan dan Penanganan Risiko Strategis Baru dan Tidak Terantisipasi MRPN 5 Termin 5 Laporan Konsolidasi Kepatuhan dan Risiko Strategis Baru dan Tidak Terantisipasi MRPN 6 Termin 6 Laporan Penyusunan Kajian Kepatuhan dan Risiko Strategis Baru dan Tidak Terantisipasi Manajemen Risiko Pembangunan Nasional (MRPN)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1873512);
