INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64999833', 64999833, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'BALAI POM KOTA SURAKARTA', '6384. Alat Tulis Kantor', 'Barang', 'E-Purchasing', 'Jawa Tengah, Surakarta (Kota)', 27000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Tersedianya Alat Tulis Kantor yang sesuai dengan spesifikasi teknis, tepat jumlah, dan tepat waktu guna mendukung kinerja pegawai Balai POM di Surakarta', '1. Kelompok Kertas (Paper Based) Fokus pada ketahanan penyimpanan (arsip) dan kelancaran mesin cetak. • Kertas HVS A4 & F4: o Gramasi: Minimal 80 gsm (untuk mencegah paper jam dan tembus tinta/dual-side printing). o Sertifikasi: Wajib memiliki sertifikat FSC atau PEFC (kelestarian hutan) dan SNI. 2. Kelompok Alat Tulis (Writing Tools) • Pulpen Gel: o Jenis Tinta: Water-resistant dan Fade-resistant (agar tanda tangan pada dokumen resmi tidak luntur). o Warna: Hitam dan Biru. • Pensil & Peralatan Gambar: o Pensil 2B standar komputer (untuk pengisian form survei/uji). o Highlighter (Stabilo) dengan warna neon cerah, tidak merusak tulisan di bawahnya. 3. Kelompok Consumables Printer (Vital) Mengingat tingginya intensitas cetak laporan pengawasan obat dan makanan. • Tinta/Toner Printer: o Kriteria: Wajib 100% ORIGINAL dari produsen printer (OEM). o Keamanan: Segel kemasan harus memiliki hologram keamanan yang valid (bisa dicek via aplikasi resmi merek terkait). o Kondisi: Dus tidak penyok dan tanggal produksi tidak lebih dari 1 tahun saat dikirim. 4. Kelompok Pengarsipan (Filing System) Penting untuk penyimpanan dokumen hasil pengujian laboratorium. • Ordner (Binder): o Bahan: Karton tebal dilapisi PVC (anti air/lembab). o Mekanisme: Ring pengunci baja anti karat dengan sistem Rado. o Ukuran: F4 dengan lebar punggung 5 cm atau 7 cm. • Map Folder: o Bahan Plastik PP (Polypropylene) bening atau warna transparan, ketebalan minimal 0.18 micron. 5. Kelompok Alat Pendukung (Office Tools) • Stapler & Staples: Material logam penuh (heavy duty), tahan karat, ukuran No. 10 dan No. 3. • Sticky Notes: Daya rekat kuat (ultra-stick), tidak meninggalkan bekas lem saat dilepas dari dokumen resmi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1873568);
