INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65044409', 65044409, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Pengembangan Rencana Tindak Lanjut (Action Plan) Penguatan Strategi Budaya Risiko Manajemen Risiko Pembangunan Nasional (MRPN)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 97944000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '00', 'Lingkup kegiatan dan tanggung jawab untuk Jasa Konsultan Pengembangan Rencana Tindak Lanjut (Action Plan) Penguatan Strategi Budaya Risiko Manajemen Risiko Pembangunan Nasional (MRPN) adalah sebagai berikut: Penyusunan direktori pembelajaran dan penerapan budaya risiko, yang memuat referensi kebijakan, praktik baik, metodologi, serta perangkat pendukung yang dapat digunakan sebagai panduan dalam pengembangan dan penguatan budaya risiko; Mengidentifikasi dan memetakan materi dan modul pembelajaran yang relevan dengan pengembangan strategi budaya risiko; Pemberian dukungan pelaksanaan asistensi dan fasilitasi pengembangan kapasitas sumber daya manusia dalam rangka meningkatkan pemahaman dan menerapkan prinsip-prinsip budaya risiko; Penyusunan modul kerangka kerja (framework) Pengembangan Strategi Budaya Risiko yang selaras dengan kebijakan, strategi dan tata kelola lingkup sistem dan manajemen risiko; Perumusan strategi rencana tindak lanjut (action plan) penguatan budaya risiko, yang disusun berdasarkan hasil evaluasi, pembelajaran, dan temuan pelaksanaan asistensi untuk mendukung penerapan budaya risiko secara berkelanjutan; Penyusunan laporan asistensi strategis Pengembangan Strategi Budaya Risiko, yang membuat rangkaian kegiatan, analisis hasil asistensi, rekomendasi penguatan kelembagaan, dan pengambilan kebijakan; dan Penyusunan laporan akhir Jasa Konsultan Pengembangan Rencana Tindak Lanjut (Action Plan) Penguatan Strategi Budaya Risiko Manajemen Risiko Pembangunan Nasional (MRPN).', 'Keluaran Jasa Konsultan Pengembangan Rencana Tindak Lanjut (Action Plan) Penguatan Strategi Budaya Risiko Manajemen Risiko Pembangunan Nasional (MRPN) meliputi penyusunan direktori pembelajaran dan penerapan budaya risiko yang memuat referensi kebijakan, praktik terbaik (best practices), metodologi, serta berbagai perangkat pendukung yang dapat digunakan sebagai pedoman dalam pengembangan dan penguatan budaya risiko secara sistematis dan berkelanjutan. Selain itu, dilakukan identifikasi dan pemetaan terhadap materi serta modul pembelajaran yang relevan guna mendukung perumusan dan implementasi strategi budaya risiko yang selaras dengan kebutuhan dan karakteristik organisasi. Dalam rangka meningkatkan pemahaman, kompetensi, dan kapasitas sumber daya manusia, diberikan dukungan melalui pelaksanaan asistensi dan fasilitasi pengembangan kapasitas agar prinsip-prinsip budaya risiko dapat dipahami, diinternalisasi, dan diterapkan secara efektif di seluruh tingkatan organisasi. Selanjutnya, disusun modul kerangka kerja (framework) Pengembangan Strategi Budaya Risiko yang terintegrasi dan selaras dengan kebijakan, strategi, serta tata kelola dalam lingkup sistem dan manajemen risiko organisasi. Berdasarkan hasil evaluasi, proses pembelajaran, serta temuan yang diperoleh selama pelaksanaan asistensi, dirumuskan strategi rencana tindak lanjut (action plan) penguatan budaya risiko guna memastikan keberlanjutan dan efektivitas penerapannya. Seluruh rangkaian kegiatan tersebut kemudian didokumentasikan dalam laporan asistensi strategis Pengembangan Strategi Budaya Risiko yang memuat uraian pelaksanaan kegiatan, analisis hasil asistensi, serta rekomendasi penguatan kelembagaan dan pengambilan kebijakan. Sebagai penutup, disusun Laporan Pengembangan Rencana Tindak Lanjut (Action Plan) Penguatan Strategi Budaya Risiko Manajemen Risiko Pembangunan Nasional (MRPN) sebagai bentuk pertanggungjawaban pelaksanaan kegiatan sekaligus sebagai rujukan dalam penguatan budaya risiko di masa mendatang. Sehubungan dengan pelaksanaan kegiatan tersebut, penyampaian keluaran Jasa Konsultan Pengembangan Rencana Tindak Lanjut (Action Plan) Penguatan Strategi Budaya Risiko Manajemen Risiko Pembangunan Nasional (MRPN) dilakukan secara bertahap dan dituangkan dalam laporan per termin. Sebagai berikut rinciannya: No Periode Keluaran per Termin 1 Termin 1 Laporan Direktori Pembelajaran dan Penerapan Budaya Risiko 2 Termin 2 Laporan Pemetaan Materi dan Modul Pembelajaran Pengembangan Strategi Budaya Risiko 3 Termin 3 Laporan Bahan Asistensi Penguatan Pemahaman Budaya Risiko 4 Termin 4 Laporan Kerangka Kerja (Framework) Pengembangan Strategi Budaya Risiko 5 Termin 5 Laporan Rencana Tindak Lanjut (Action Plan) Penguatan Budaya Risiko 6 Termin 6 Laporan Pengembangan Rencana Tindak Lanjut (Action Plan) Penguatan Strategi Budaya Risiko Manajemen Risiko Pembangunan Nasional (MRPN)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1876001);
